\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'FAIL accepted %',q;end$$;
insert into auth.users(id,email) values('70000000-0000-4000-8000-000000000001','journey-publish-owner@example.test'),('70000000-0000-4000-8000-000000000099','journey-publish-other@example.test');
select public.create_staging_business('70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002','Journey','journey-publication','UTC','USD','HOUSEKEEPING','journey_publication_owner');
select public.create_staging_business('70000000-0000-4000-8000-000000000099','70000000-0000-4000-8000-000000000098','Foreign','journey-publication-other','UTC','USD','HOUSEKEEPING','journey_publication_other');
insert into public.services(id,tenant_id,name,archetype,currency,base_price,duration_minutes) values('70000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000002','Cleaning','simple','USD',12500,60);
create function pg_temp.journey(reordered boolean default false) returns jsonb language sql as $$select jsonb_build_object('schemaVersion',1,'stages',jsonb_agg(jsonb_build_object('id',kind,'kind',kind,'label',kind,'enabled',kind<>'options') order by n)) from unnest(case when reordered then array['service','options','information','schedule','review_payment','confirmation'] else array['service','options','schedule','information','review_payment','confirmation'] end) with ordinality s(kind,n)$$;
create function pg_temp.save(r bigint default 0,reordered boolean default false,f uuid default '70000000-0000-4000-8000-000000000004') returns jsonb language sql as $$select public.save_paid_journey_draft('70000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000002',f,'70000000-0000-4000-8000-000000000003',r,'Journey','{"accentColor":"#4f46e5","layout":"stacked"}',pg_temp.journey(reordered))$$;
create function pg_temp.publish(r bigint default 1,v uuid default '70000000-0000-4000-8000-000000000005',i uuid default '70000000-0000-4000-8000-000000000006',o jsonb default '["https://checkout.example.test"]',approved jsonb default '["https://checkout.example.test"]',a uuid default '70000000-0000-4000-8000-000000000001',t uuid default '70000000-0000-4000-8000-000000000002',f uuid default '70000000-0000-4000-8000-000000000004') returns jsonb language sql as $$select public.publish_paid_journey_draft(a,t,f,r,v,i,o,approved)$$;
select pg_temp.save();
select pg_temp.publish();
create function pg_temp.issue(h text default repeat('a',64),i uuid default '70000000-0000-4000-8000-000000000006',o text default 'https://checkout.example.test') returns jsonb language sql as $$select public.issue_paid_journey_session(i,h,o)$$;
select pg_temp.issue();
select pg_temp.assert(pg_temp.issue()=public.resolve_paid_journey_session(repeat('a',64),'https://checkout.example.test'),'same hash replay exact receipt and expiry');
select pg_temp.assert((select count(*)=1 from public.paid_journey_sessions),'one replay session');
select pg_temp.assert(not(pg_temp.issue() ?| array['tokenHash','tenantId','actorId','flowId','serviceId']),'private provenance stripped');
select pg_temp.assert((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.paid_journey_sessions'::regclass),'forced RLS');
select pg_temp.assert(not has_table_privilege('service_role','public.paid_journey_sessions','select,insert,update,delete'),'no raw service grants');
set local role anon;select pg_temp.reject($q$select public.issue_paid_journey_session('70000000-0000-4000-8000-000000000006',repeat('b',64),'https://checkout.example.test')$q$,'42501');reset role;
select pg_temp.reject($q$select pg_temp.issue('weak')$q$,'22023');
select pg_temp.reject($q$select pg_temp.issue(repeat('b',64),o=>'*')$q$,'22023');
select pg_temp.reject($q$select pg_temp.issue(repeat('b',64),o=>'https://foreign.example.test')$q$,'P0002');
select pg_temp.reject($q$select public.resolve_paid_journey_session(repeat('a',64),'https://foreign.example.test')$q$,'42501');
select pg_temp.reject($q$insert into public.paid_journey_sessions select repeat('f',64),'70000000-0000-4000-8000-000000000098',flow_id,version_id,installation_id,service_id,origin,issued_at,expires_at from public.paid_journey_sessions$q$,'55000');
select pg_temp.reject($q$update public.paid_journey_sessions set expires_at=expires_at+interval '1 minute'$q$,'55000');
select pg_temp.reject($q$delete from public.paid_journey_sessions$q$,'55000');
insert into public.paid_journey_sessions select repeat('e',64),tenant_id,flow_id,version_id,installation_id,service_id,origin,stamp-interval '16 minutes',stamp-interval '1 minute' from public.paid_journey_sessions cross join (select clock_timestamp() stamp) s limit 1;
select pg_temp.reject($q$select public.resolve_paid_journey_session(repeat('e',64),'https://checkout.example.test')$q$,'42501');
select pg_temp.reject($q$select pg_temp.issue(repeat('e',64))$q$,'42501');
update public.services set base_price=12600 where id='70000000-0000-4000-8000-000000000003';
select pg_temp.reject($q$select pg_temp.issue(repeat('b',64))$q$,'40001');
select pg_temp.reject($q$select public.resolve_paid_journey_session(repeat('a',64),'https://checkout.example.test')$q$,'40001');
update public.services set base_price=12500,active=false where id='70000000-0000-4000-8000-000000000003';
select pg_temp.reject($q$select pg_temp.issue(repeat('b',64))$q$,'P0002');
update public.services set active=true where id='70000000-0000-4000-8000-000000000003';
update public.tenants set status='suspended' where id='70000000-0000-4000-8000-000000000002';
select pg_temp.reject($q$select pg_temp.issue(repeat('b',64))$q$,'P0002');
update public.tenants set status='active' where id='70000000-0000-4000-8000-000000000002';
select pg_temp.save(1,true);select pg_temp.publish(r=>2,v=>'70000000-0000-4000-8000-000000000025',i=>'70000000-0000-4000-8000-000000000026');
select pg_temp.reject($q$select public.resolve_paid_journey_session(repeat('a',64),'https://checkout.example.test')$q$,'P0002');
select pg_temp.issue(repeat('b',64),'70000000-0000-4000-8000-000000000026');
select pg_temp.reject($q$select pg_temp.issue(repeat('b',64))$q$,'P0002');
select pg_temp.assert((select count(*) from public.flow_sessions)=0 and (select count(*) from public.flow_requests)=0 and (select count(*) from public.bookings)=0 and (select count(*) from public.payments)=0 and (select count(*) from public.capacity_holds)=0,'no legacy or financial writer');
rollback;
\echo PASS V8 isolated sessions provenance current catalog expiry replay ACL and no financial writes
